<!DOCTYPE html>
<html>
<head>
  <title>Ledger</title>
</head>
<body>
  <h2>Ledger</h2>
  <input id="find" type="text">
  <span id="match-count">0 items visible</span>
  <button id="clear-filter">Clear Filter</button>
  <table id="book"><tbody>
    <tr class="line"><td>Freight</td></tr>
    <tr class="line"><td>Freezer</td></tr>
    <tr class="line"><td>Postage</td></tr>
    <tr class="line"><td>Postal</td></tr>
    <tr class="line"><td>Utilities</td></tr>
  </tbody></table>
  <script>
    var lines = [].slice.call(document.querySelectorAll('#book .line'));
    var finder = document.getElementById('find');
    var clearFilter = document.getElementById('clear-filter');
    var matchCount = document.getElementById('match-count');

    function updateMatchCount() {
      var visibleCount = lines.filter(function (tr) {
        return tr.style.display !== 'none';
      }).length;
      matchCount.textContent = visibleCount + ' items visible';
    }

    function sift() {
      var q = finder.value.toLowerCase();
      lines.forEach(function (tr) {
        tr.style.display = tr.textContent.toLowerCase().indexOf(q) === -1 ? 'none' : '';
      });
      updateMatchCount();
    }

    document.addEventListener('input', function (e) {
      if (e.target && e.target.id === 'find') sift();
    });

    clearFilter.addEventListener('click', function () {
      finder.value = '';
      lines.forEach(function (tr) {
        tr.style.display = '';
      });
      updateMatchCount();
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') {
        finder.value = '';
        lines.forEach(function (tr) {
          tr.style.display = '';
        });
        updateMatchCount();
      }
    });

    // Initialize match count
    updateMatchCount();
  </script>
</body>
</html>
